    55  static int dns_label_add(fr_dns_labels_t *lb, uint8_t const *start, uint8_t const *end)
    56  {
    57          size_t offset, size = end - start;
    58          fr_dns_block_t *block;
    59
    60          /*
    61           *      If we don't care about tracking the blocks, then don't
    62           *      do anything.
    63           */
    64          if (!lb) return 0;
    65
    66          fr_assert(start >= lb->start);
    67          fr_assert(end >= start);
    68
    69          offset = start - lb->start;
    70          fr_assert(offset < 65536);
    71          fr_assert(size < 65535);
    72          fr_assert((offset + size) < 65535);
    73
    74          FR_PROTO_TRACE("adding label at offset %zu", offset);
    75
    76          if (offset > 65535) return -1;
    77          if (size > 65535) return -1;
    78          if ((offset + size) > 65535) return -1;
    79
    80          /*
    81           *      We add blocks append-only.  No adding new blocks in
    82           *      the middle of a packet.
    83           */
    84          block = &lb->blocks[lb->num - 1];
    85          fr_assert(block->start <= offset);
    86          fr_assert(offset);
    87
    88          FR_PROTO_TRACE("Last block (%d) is %u..%u", lb->num - 1, block->start, block->end);
    89
    90          /*
    91           *      Fits within an existing block.
    92           */
    93          if (block->end == offset) {
    94                  block->end += size;
    95                  FR_PROTO_TRACE("Expanding last block (%d) to %u..%u", lb->num - 1, block->start, block->end);
    96                  return 0;
    97          }
    98
    99          /*
   100           *      It's full, die.
   101           */
   102          if (lb->num == lb->max) return -1;
   103
   104          lb->num++;
   105          block++;
   106
   107          block->start = offset;
   108          block->end = offset + size;
   109          FR_PROTO_TRACE("Appending block (%d) to %u..%u", lb->num - 1, block->start, block->end);
   110
   111          return 0;
   112  }
