   114  static bool dns_pointer_valid(fr_dns_labels_t *lb, uint16_t offset)
   115  {
   116          int i;
   117
   118          if (!lb) return true;   /* we have no idea, so allow it */
   119
   120          for (i = 0; i < lb->num; i++) {
   121                  FR_PROTO_TRACE("Checking block %d %u..%u against %u",
   122                                 i, lb->blocks[i].start, lb->blocks[i].end, offset);
   123
   124                  if (offset < lb->blocks[i].start) return false;
   125
   126                  if (offset < lb->blocks[i].end) return true;
   127          }
   128
   129          return false;
   130  }
